<div class="admin-page-head"><h1>تنظیمات وبسایت</h1></div><?php if($error): ?><div class="flash flash-error"><?= CHtml::encode($error) ?></div><?php endif; ?>
<?= CHtml::beginForm('','post') ?><section class="panel"><h2>هویت و ارتباط</h2><?php foreach(array('site_name'=>'نام سایت','site_description'=>'معرفی سایت','announcement'=>'نوار اطلاع‌رسانی','footer_text'=>'متن پایین سایت','contact_phone'=>'تلفن تماس','contact_email'=>'ایمیل تماس') as $key=>$label): ?><div class="field"><label for="<?= $key ?>"><?= $label ?></label><?= CHtml::textField($key,ShopSettings::get($key,''),array('id'=>$key)) ?></div><?php endforeach; ?></section>
<section class="panel"><h2>فروشگاه یا کاتالوگ</h2><div class="check-field"><?= CHtml::checkBox('commerce_enabled',Commerce::enabled(),array('value'=>'1')) ?><label for="commerce_enabled">امکان خرید و ثبت سفارش فعال باشد</label></div><p class="muted">با خاموش‌کردن خرید، سایت به کاتالوگ تبدیل می‌شود و ثبت سفارش جدید مسدود می‌شود. مدیریت سفارش‌های قبلی همچنان در دسترس است.</p><div class="check-field"><?= CHtml::checkBox('catalog_show_prices',ShopSettings::get('catalog_show_prices','1')==='1',array('value'=>'1')) ?><label for="catalog_show_prices">قیمت محصولات در حالت کاتالوگ نمایش داده شود</label></div><div class="form-row"><div class="field"><label>واحد نمایش و ورود قیمت</label><?= CHtml::dropDownList('currency',ShopSettings::get('currency'),array('toman'=>'تومان','rial'=>'ریال')) ?></div><div class="field"><label>مهلت رزرو سفارش (دقیقه)</label><?= CHtml::numberField('reservation_minutes',ShopSettings::get('reservation_minutes'),array('min'=>1,'max'=>10080,'required'=>true)) ?></div></div><p class="muted">تغییر واحد، ارزش مبالغ را حفظ می‌کند. مدت رزرو جدید برای سفارش‌های بعدی اعمال می‌شود.</p></section>
<section class="panel"><h2>آمار بازدید</h2><div class="check-field"><?= CHtml::checkBox('analytics_enabled',VisitService::enabled(),array('value'=>'1')) ?><label for="analytics_enabled">ثبت آمار ناشناس بازدید فعال باشد</label></div><div class="field"><label>مدت نگهداری آمار (۷ تا ۳۶۵ روز)</label><?= CHtml::numberField('analytics_retention_days',ShopSettings::get('analytics_retention_days',90),array('min'=>7,'max'=>365,'required'=>true)) ?></div><h3>اتصال اختیاری Matomo</h3><p class="muted">آمار داخلی بدون سرویس بیرونی کار می‌کند. اگر Matomo دارید، آدرس HTTPS و شناسه سایت را وارد کنید. درخواست عدم ردیابی مرورگر در هر دو روش رعایت می‌شود؛ Matomo بدون کوکی اجرا می‌شود.</p><div class="form-row"><div class="field"><label>آدرس Matomo</label><?= CHtml::urlField('matomo_url',ShopSettings::get('matomo_url',''),array('placeholder'=>'https://analytics.example.com/','dir'=>'ltr')) ?></div><div class="field"><label>شناسه سایت Matomo</label><?= CHtml::textField('matomo_site_id',ShopSettings::get('matomo_site_id',''),array('inputmode'=>'numeric')) ?></div></div></section><section class="panel"><h2>ارسال سفارش</h2><?php foreach(array('shipping_fee'=>'هزینه ارسال عادی','shipping_free_threshold'=>'حداقل خرید برای ارسال رایگان؛ صفر یعنی غیرفعال') as $key=>$label): ?><div class="field"><label for="<?= $key ?>"><?= $label ?> (<?= Money::unit() ?>)</label><?= CHtml::textField($key,Money::input(ShopSettings::get($key,0)),array('class'=>'money-input')) ?></div><?php endforeach; ?></section><?php if(AccessService::isSuperAdmin()): ?><section class="panel"><h2>درگاه پرداخت زرین‌پال</h2><p class="muted">تا تکمیل اطلاعات، درگاه را غیرفعال نگه دارید. مبالغ به ریال برای درگاه ارسال می‌شوند.</p><div class="check-field"><?= CHtml::checkBox('zarinpal_enabled',ShopSettings::get('zarinpal_enabled','0')==='1',array('value'=>'1')) ?><label for="zarinpal_enabled">پرداخت آنلاین فعال باشد</label></div><div class="field"><label for="zarinpal_merchant">Merchant ID</label><?= CHtml::textField('zarinpal_merchant',ShopSettings::get('zarinpal_merchant',''),array('dir'=>'ltr','maxlength'=>36,'autocomplete'=>'off')) ?></div><div class="field"><label for="zarinpal_mode">حالت درگاه</label><?= CHtml::dropDownList('zarinpal_mode',ShopSettings::get('zarinpal_mode','sandbox'),array('sandbox'=>'آزمایشی','live'=>'واقعی')) ?></div><div class="field"><label for="public_url">آدرس عمومی سایت</label><?= CHtml::urlField('public_url',ShopSettings::get('public_url',''),array('dir'=>'ltr','placeholder'=>'https://example.com')) ?></div></section><?php endif; ?><?php if(AccessService::isSuperAdmin()): ?><section class="panel"><h2>کش و سرعت سایت</h2><div class="form-row"><div class="field"><label for="cache_backend">محل نگهداری کش</label><?= CHtml::dropDownList('cache_backend',ShopSettings::get('cache_backend','db'),array('db'=>'دیتابیس (پیش‌فرض)','file'=>'فایل روی دیسک','off'=>'غیرفعال')) ?></div><div class="field"><label for="cache_ttl">مدت نگهداری (ثانیه)</label><?= CHtml::numberField('cache_ttl',ShopSettings::get('cache_ttl','600'),array('min'=>30,'max'=>86400,'required'=>true)) ?></div></div><p class="muted">منوها، درخت دسته‌بندی، فیلتر مشخصات محصولات و کاتالوگ‌ها کش می‌شوند. با تغییر داده‌ها، کش مرتبط خودکار باطل می‌شود. موجودی، سبد خرید و پرداخت همیشه از داده تازه استفاده می‌کنند. تغییر محل کش از درخواست بعد اعمال می‌شود.</p></section><?php endif; ?><?= CHtml::submitButton('ذخیره تنظیمات',array('class'=>'btn btn-primary')) ?><?= CHtml::endForm() ?>

